using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CustomEventSetupConditionToBeSelected", menuName = "Data/BattleSceneSetups/Events/CustomEventSetupConditionToBeSelected", order = 0)]
public class CustomEventSetupConditionToBeSelected : ScriptableObject
{
	[Header("Blessings")]
	[SerializeField]
	private List<OmenData> blessingsThatMuteEventWhenPlayerHasAnyOfThem = new List<OmenData>();

	[SerializeField]
	private List<OmenData> blessingsThatMuteEventWhenPlayerHasAllOfThem = new List<OmenData>();

	[Header("Dice Pool")]
	[SerializeField]
	private bool anyDiceOnPool;

	[SerializeField]
	private bool anyStarterDieOnPool;

	[SerializeField]
	private bool atLeastOneDieThatIsNotAStarterOnPool;

	[SerializeField]
	private int atLeastXDieThatIsNotAStarterOnPool;

	[Header("Sentinel")]
	[SerializeField]
	private bool haveAtLeastOneSentinel;

	protected AssetsReference assetsReference => ReferenceSingleton<AssetsReference>.Instance;

	public virtual bool CheckConditionToBeSelected()
	{
		if (blessingsThatMuteEventWhenPlayerHasAnyOfThem.Count > 0 && assetsReference.PlayerCurrentOmens.PlayerHasAnyOfThisBlessings(blessingsThatMuteEventWhenPlayerHasAnyOfThem))
		{
			return false;
		}
		if (blessingsThatMuteEventWhenPlayerHasAllOfThem.Count > 0 && assetsReference.PlayerCurrentOmens.PlayerHasAllOfTheseBlessings(blessingsThatMuteEventWhenPlayerHasAllOfThem))
		{
			return false;
		}
		if (anyDiceOnPool && assetsReference.DicePool.GetDicesAmount() == 0)
		{
			return false;
		}
		if (anyStarterDieOnPool && assetsReference.DicePool.GetDiceAmountFromSpecificTier(assetsReference.StarterDieTier) == 0)
		{
			return false;
		}
		if (atLeastOneDieThatIsNotAStarterOnPool && assetsReference.DicePool.GetDiceAmountExceptSpecificTier(assetsReference.StarterDieTier) == 0)
		{
			return false;
		}
		if (atLeastXDieThatIsNotAStarterOnPool > 0 && assetsReference.DicePool.GetDiceAmountExceptSpecificTier(assetsReference.StarterDieTier) < atLeastXDieThatIsNotAStarterOnPool)
		{
			return false;
		}
		if (haveAtLeastOneSentinel && assetsReference.CurrentCompanions.RuntimeCompanions.Count == 0)
		{
			return false;
		}
		return true;
	}
}
